1	//! Plugin scaffold template.
2	//!
3	//! Copy this file when rebuilding a plugin from scratch. Keep the ENTRY and
4	//! EXIT blocks intact so every plugin has the same audit shape:
5	//! - ENTRY owns identity, typed state, and typed method contracts.
6	//! - EXIT publishes the PluginSchema contract consumed by D-Bus, The Sled,
7	//!   gRPC, reflection, MCP, and the GUI renderer.
8	//!
9	//! Do not put this file in `mod.rs`; it is a template, not compiled source.
10	
11	use anyhow::Result;
12	use async_trait::async_trait;
13	use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
14	use op_state_store::{PluginSchema, SideEffect};
15	use serde::{Deserialize, Serialize};
16	use simd_json::{json, OwnedValue as Value};
17	
18	use super::plugin_scaffold_helpers::{
19	    method_decl_from_schemars_with_output, schema_from_state, AckOutput,
20	};
21	
22	// =============================================================================
23	// PLUGIN ENTRY: identity and typed schema seed
24	// =============================================================================
25	
26	const PLUGIN_NAME: &str = "replace_me";
27	const PLUGIN_VERSION: &str = "1.0.0";
28	const PLUGIN_CATEGORY: &str = "replace_me";
29	const PLUGIN_DESCRIPTION: &str = "Replace with the plugin's D-Bus contract purpose.";
30	
31	#[derive(Debug, Clone, Default)]
32	pub struct ReplaceMePlugin;
33	
34	impl ReplaceMePlugin {
35	    pub fn new() -> Self {
36	        Self
37	    }
38	}
39	
40	/// The plugin's published live-state contract.
41	///
42	/// This struct is the schemars seed. Add fields here first, with OSCAL subids,
43	/// then let schema-output-processor turn it into PluginSchema output.
44	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
45	#[schemars(extend("x-oscal-subid" = "sch.software.plugin.replace-me.schema@v1"))]
46	pub struct ReplaceMeState {
47	    #[serde(default)]
48	    #[schemars(extend("x-oscal-subid" = "obs.software.plugin.replace-me.status@v1"))]
49	    pub status: String,
50	}
51	
52	impl Default for ReplaceMeState {
53	    fn default() -> Self {
54	        Self {
55	            status: "ready".to_string(),
56	        }
57	    }
58	}
59	
60	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
61	#[schemars(extend("x-oscal-subid" = "obs.software.plugin.replace-me.get-status.input@v1"))]
62	pub struct GetStatusInput {}
63	
64	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
65	#[schemars(extend("x-oscal-subid" = "obs.software.plugin.replace-me.get-status.output@v1"))]
66	pub struct GetStatusOutput {
67	    pub status: String,
68	}
69	
70	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
71	#[schemars(extend("x-oscal-subid" = "mut.software.plugin.replace-me.set-status.input@v1"))]
72	pub struct SetStatusInput {
73	    pub status: String,
74	}
75	
76	// =============================================================================
77	// PLUGIN BODY: D-Bus-backed behavior only
78	// =============================================================================
79	
80	#[async_trait]
81	impl StatePlugin for ReplaceMePlugin {
82	    fn name(&self) -> &str {
83	        PLUGIN_NAME
84	    }
85	
86	    fn version(&self) -> &str {
87	        PLUGIN_VERSION
88	    }
89	
90	    fn schema(&self) -> Option<PluginSchema> {
91	        Some(replace_me_schema())
92	    }
93	
94	    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
95	        Ok(StateDiff {
96	            plugin: PLUGIN_NAME.to_string(),
97	            actions: vec![],
98	            metadata: DiffMetadata {
99	                timestamp: chrono::Utc::now().timestamp(),
100	                current_hash: String::new(),
101	                desired_hash: String::new(),
102	            },
103	        })
104	    }
105	
106	    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
107	        Ok(ApplyResult {
108	            success: true,
109	            changes_applied: vec![],
110	            errors: vec![],
111	            checkpoint: None,
112	        })
113	    }
114	
115	    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
116	        Ok(true)
117	    }
118	
119	    async fn create_checkpoint(&self) -> Result<Checkpoint> {
120	        Ok(Checkpoint {
121	            id: format!("{}-checkpoint", PLUGIN_NAME),
122	            plugin: PLUGIN_NAME.to_string(),
123	            timestamp: chrono::Utc::now().timestamp(),
124	            state_snapshot: json!({}),
125	            backend_checkpoint: None,
126	        })
127	    }
128	
129	    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
130	        Ok(())
131	    }
132	
133	    fn capabilities(&self) -> PluginCapabilities {
134	        PluginCapabilities {
135	            supports_rollback: false,
136	            supports_checkpoints: true,
137	            supports_verification: true,
138	            atomic_operations: true,
139	        }
140	    }
141	}
142	
143	// =============================================================================
144	// PLUGIN EXIT: publish the single PluginSchema contract
145	// =============================================================================
146	
147	pub(crate) fn replace_me_schema() -> PluginSchema {
148	    let state = serde_json::to_value(ReplaceMeState::default())
149	        .expect("plugin state serializes")
150	        .to_string();
151	    let mut state = state.into_bytes();
152	    let state = simd_json::to_owned_value(&mut state).expect("plugin state is valid JSON");
153	
154	    let mut schema = schema_from_state(
155	        PLUGIN_NAME,
156	        PLUGIN_CATEGORY,
157	        PLUGIN_VERSION,
158	        PLUGIN_DESCRIPTION,
159	        &state,
160	    );
161	
162	    schema.methods.insert(
163	        "get_status".to_string(),
164	        method_decl_from_schemars_with_output::<GetStatusInput, GetStatusOutput>(
165	            "get_status",
166	            SideEffect::Read,
167	            true,
168	            "replace_me.read",
169	            "obs.software.plugin.replace-me.status.get@v1",
170	        ),
171	    );
172	
173	    schema.methods.insert(
174	        "set_status".to_string(),
175	        method_decl_from_schemars_with_output::<SetStatusInput, AckOutput>(
176	            "set_status",
177	            SideEffect::Mutation,
178	            false,
179	            "replace_me.invoke",
180	            "mut.software.plugin.replace-me.status.set@v1",
181	        ),
182	    );
183	
184	    schema
185	}
186	
187	inventory::submit! {
188	    crate::default_registry::PluginReg::new(PLUGIN_NAME, |_ctx| std::sync::Arc::new(ReplaceMePlugin::new()))
189	}
