1	//! Translator layer: schemars-derived JSON Schema 2020-12 -> `PluginSchema`.
2	//!
3	//! Schemars is the seed; it disappears at this boundary — no consumer ever
4	//! reads schemars output directly (spec Key Decision 1/2). Moved from
5	//! `op-plugins/src/state_plugins/schemars_adapter.rs` and
6	//! `op-plugins/src/state_plugins/plugin_scaffold_helpers.rs` so op-blob is the
7	//! single cohesive schema-pipeline crate.
8	
9	use op_state_store::{Constraint, FieldSchema, FieldType, MethodDecl, PluginSchema, SideEffect};
10	use serde::{Deserialize, Serialize};
11	use serde_json::{Map, Value as JVal};
12	use simd_json::prelude::*;
13	use simd_json::OwnedValue;
14	use std::collections::{HashMap, HashSet};
15	
16	/// Build a `PluginSchema` from the JSON of a schemars-derived schema.
17	///
18	/// The root type's top-level properties become the plugin's `fields`; `$ref`s
19	/// into `$defs`/`definitions` are resolved inline so nested structs expand
20	/// correctly. Root/field `x-oscal-subid` extensions populate `subids`;
21	/// `x-immutable-paths` populates `immutable_paths`.
22	pub fn plugin_schema_from_json(
23	    name: &str,
24	    version: &str,
25	    description: &str,
26	    root: &JVal,
27	) -> PluginSchema {
28	    let defs = root
29	        .get("$defs")
30	        .or_else(|| root.get("definitions"))
31	        .and_then(JVal::as_object);
32	
33	    let top = resolve(root, defs);
34	    let required = required_set(top);
35	
36	    let mut fields = HashMap::new();
37	    let mut subids = HashMap::new();
38	    if let Some(props) = top.get("properties").and_then(JVal::as_object) {
39	        for (fname, fnode) in props {
40	            let req = required.contains(fname.as_str());
41	            fields.insert(fname.clone(), field_schema(fnode, defs, req));
42	            if let Some(subid) = fnode.get("x-oscal-subid").and_then(JVal::as_str) {
43	                subids.insert(fname.clone(), subid.to_string());
44	            }
45	        }
46	    }
47	
48	    if let Some(subid) = root.get("x-oscal-subid").and_then(JVal::as_str) {
49	        subids.insert("__schema__".to_string(), subid.to_string());
50	    }
51	
52	    let mut schema = PluginSchema::builder(name)
53	        .version(version)
54	        .description(description)
55	        .build();
56	    schema.fields = fields;
57	    schema.subids = subids;
58	    if let Some(paths) = root.get("x-immutable-paths").and_then(JVal::as_array) {
59	        schema.immutable_paths = paths
60	            .iter()
61	            .filter_map(|v| v.as_str().map(String::from))
62	            .collect();
63	    }
64	    schema
65	}
