67	fn resolve<'a>(node: &'a JVal, defs: Option<&'a Map<String, JVal>>) -> &'a JVal {
68	    if let (Some(r), Some(d)) = (node.get("$ref").and_then(JVal::as_str), defs) {
69	        if let Some(key) = r.rsplit('/').next() {
70	            if let Some(target) = d.get(key) {
71	                return resolve(target, defs);
72	            }
73	        }
74	    }
75	    node
76	}
77	
78	fn required_set(node: &JVal) -> HashSet<String> {
79	    node.get("required")
80	        .and_then(JVal::as_array)
81	        .map(|a| {
82	            a.iter()
83	                .filter_map(|v| v.as_str().map(String::from))
84	                .collect()
85	        })
86	        .unwrap_or_default()
87	}
88	
89	fn field_type(node: &JVal, defs: Option<&Map<String, JVal>>) -> FieldType {
90	    let node = resolve(node, defs);
91	
92	    if let Some(alternatives) = node
93	        .get("anyOf")
94	        .or_else(|| node.get("oneOf"))
95	        .and_then(JVal::as_array)
96	    {
97	        let non_null: Vec<&JVal> = alternatives
98	            .iter()
99	            .filter(|a| type_str(a) != Some("null"))
100	            .collect();
101	        match non_null.as_slice() {
102	            [] => {}
103	            [single] => return field_type(single, defs),
104	            many => {
105	                return FieldType::OneOf(many.iter().map(|a| field_type(a, defs)).collect());
106	            }
107	        }
108	    }
109	
110	    if let Some(en) = node.get("enum").and_then(JVal::as_array) {
111	        return FieldType::Enum(
112	            en.iter()
113	                .filter_map(|v| v.as_str().map(String::from))
114	                .collect(),
115	        );
116	    }
117	
118	    match type_str(node) {
119	        Some("string") => FieldType::String,
120	        Some("integer") => FieldType::Integer,
121	        Some("number") => FieldType::Float,
122	        Some("boolean") => FieldType::Boolean,
123	        Some("array") => {
124	            let item = node
125	                .get("items")
126	                .map(|i| field_type(i, defs))
127	                .unwrap_or(FieldType::Any);
128	            FieldType::Array(Box::new(item))
129	        }
130	        Some("object") => {
131	            let req = required_set(node);
132	            let mut m = HashMap::new();
133	            if let Some(props) = node.get("properties").and_then(JVal::as_object) {
134	                for (k, v) in props {
135	                    m.insert(k.clone(), field_schema(v, defs, req.contains(k.as_str())));
136	                }
137	            }
138	            FieldType::Object(m)
139	        }
140	        _ => FieldType::Any,
141	    }
142	}
143	
144	fn type_str(node: &JVal) -> Option<&str> {
145	    match node.get("type") {
146	        Some(JVal::String(s)) => Some(s.as_str()),
147	        Some(JVal::Array(a)) => a.iter().filter_map(JVal::as_str).find(|t| *t != "null"),
148	        _ => None,
149	    }
150	}
151	
152	fn field_schema(node: &JVal, defs: Option<&Map<String, JVal>>, required: bool) -> FieldSchema {
153	    let meta = node;
154	    FieldSchema {
155	        field_type: field_type(node, defs),
156	        required,
157	        description: meta
158	            .get("description")
159	            .and_then(JVal::as_str)
160	            .unwrap_or_default()
161	            .to_string(),
162	        default: meta.get("default").map(to_simd),
163	        example: example_of(meta).map(to_simd),
164	        constraints: constraints(meta),
165	        read_only: meta
166	            .get("readOnly")
167	            .and_then(JVal::as_bool)
168	            .unwrap_or(false),
169	        read_only_when: None,
170	    }
171	}
172	
173	fn example_of(node: &JVal) -> Option<&JVal> {
174	    if let Some(first) = node
175	        .get("examples")
176	        .and_then(JVal::as_array)
177	        .and_then(|a| a.first())
178	    {
179	        return Some(first);
180	    }
181	    node.get("example")
182	}
183	
184	fn constraints(node: &JVal) -> Vec<Constraint> {
185	    let mut out = Vec::new();
186	    if let Some(m) = node.get("minimum").and_then(JVal::as_f64) {
187	        out.push(Constraint::Min { value: m });
188	    }
189	    if let Some(m) = node.get("maximum").and_then(JVal::as_f64) {
190	        out.push(Constraint::Max { value: m });
191	    }
192	    if let Some(p) = node.get("pattern").and_then(JVal::as_str) {
193	        out.push(Constraint::Pattern {
194	            regex: p.to_string(),
195	        });
196	    }
197	    out
198	}
199	
200	fn to_simd(v: &JVal) -> OwnedValue {
201	    let mut bytes = serde_json::to_vec(v).unwrap_or_default();
202	    simd_json::to_owned_value(&mut bytes).unwrap_or_else(|_| simd_json::json!(null))
203	}
