205	/// Recursively overwrite field defaults in `schema` with the values from the
206	/// serialized default state.
207	pub fn apply_state_defaults(schema: &mut PluginSchema, state: &OwnedValue) {
208	    fn set_field_defaults(field: &mut FieldSchema, value: &OwnedValue) {
209	        field.default = Some(value.clone());
210	        if let FieldType::Object(ref mut inner) = field.field_type {
211	            if let Some(obj) = value.as_object() {
212	                for (k, v) in obj.iter() {
213	                    if let Some(f) = inner.get_mut(k.as_str()) {
214	                        set_field_defaults(f, v);
215	                    }
216	                }
217	            }
218	        }
219	    }
220	
221	    if let Some(obj) = state.as_object() {
222	        for (k, v) in obj.iter() {
223	            if let Some(f) = schema.fields.get_mut(k.as_str()) {
224	                set_field_defaults(f, v);
225	            }
226	        }
227	    }
228	}
