261	/// Dual-generic helper that generates method declarations with typed input AND output schemas.
262	pub fn method_decl_from_schemars_with_output<
263	    Input: schemars::JsonSchema,
264	    Output: schemars::JsonSchema,
265	>(
266	    name: &str,
267	    side_effect: SideEffect,
268	    idempotent: bool,
