293	/// Full-fidelity drift diff between a reference schema and a derived schema.
294	/// Empty result = exact reproduction. Any entry must be consciously resolved.
295	pub fn schema_diffs(reference: &PluginSchema, derived: &PluginSchema) -> Vec<String> {
296	    let mut d = Vec::new();
297	    if reference.name != derived.name {
298	        d.push(format!("name: {:?} -> {:?}", reference.name, derived.name));
299	    }
300	    if reference.version != derived.version {
301	        d.push(format!(
302	            "version: {:?} -> {:?}",
303	            reference.version, derived.version
304	        ));
305	    }
306	    if reference.description != derived.description {
307	        d.push(format!(
308	            "description: {:?} -> {:?}",
309	            reference.description, derived.description
310	        ));
311	    }
312	    let (mut ir, mut id) = (
313	        reference.immutable_paths.clone(),
314	        derived.immutable_paths.clone(),
315	    );
316	    ir.sort();
317	    id.sort();
318	    if ir != id {
319	        d.push(format!("immutable_paths: {ir:?} -> {id:?}"));
320	    }
321	    if reference.subids != derived.subids {
322	        d.push(format!(
323	            "subids: {:?} -> {:?}",
324	            reference.subids, derived.subids
325	        ));
326	    }
327	    let keys: std::collections::BTreeSet<&String> = reference
328	        .fields
329	        .keys()
330	        .chain(derived.fields.keys())
331	        .collect();
332	    for k in keys {
333	        match (reference.fields.get(k), derived.fields.get(k)) {
334	            (Some(r), Some(v)) => field_diffs(&mut d, k, r, v),
335	            (Some(_), None) => d.push(format!("{k}: DROPPED (in reference, not derived)")),
336	            (None, Some(_)) => d.push(format!("{k}: ADDED (in derived, not reference)")),
337	            (None, None) => {}
338	        }
339	    }
340	    d
341	}
342	
343	fn field_diffs(d: &mut Vec<String>, prefix: &str, r: &FieldSchema, v: &FieldSchema) {
344	    if type_tag(&r.field_type) != type_tag(&v.field_type) {
345	        d.push(format!(
346	            "{prefix}.type: {} -> {}",
347	            type_tag(&r.field_type),
348	            type_tag(&v.field_type)
349	        ));
350	    }
351	    if r.required != v.required {
352	        d.push(format!(
353	            "{prefix}.required: {} -> {}",
354	            r.required, v.required
355	        ));
356	    }
357	    if r.description != v.description {
358	        d.push(format!(
359	            "{prefix}.description: {:?} -> {:?}",
360	            r.description, v.description
361	        ));
362	    }
363	    if val_str(&r.default) != val_str(&v.default) {
364	        d.push(format!(
365	            "{prefix}.default: {} -> {}",
366	            val_str(&r.default),
367	            val_str(&v.default)
368	        ));
369	    }
370	    if val_str(&r.example) != val_str(&v.example) {
371	        d.push(format!(
372	            "{prefix}.example: {} -> {}",
373	            val_str(&r.example),
374	            val_str(&v.example)
375	        ));
376	    }
377	    if constraint_tags(&r.constraints) != constraint_tags(&v.constraints) {
378	        d.push(format!(
379	            "{prefix}.constraints: {:?} -> {:?}",
380	            constraint_tags(&r.constraints),
381	            constraint_tags(&v.constraints)
382	        ));
383	    }
384	    if r.read_only != v.read_only {
385	        d.push(format!(
386	            "{prefix}.read_only: {} -> {}",
387	            r.read_only, v.read_only
388	        ));
389	    }
390	    field_type_diffs(d, prefix, &r.field_type, &v.field_type);
391	}
392	
393	fn field_type_diffs(d: &mut Vec<String>, prefix: &str, r: &FieldType, v: &FieldType) {
394	    match (r, v) {
395	        (FieldType::Array(r_inner), FieldType::Array(v_inner)) => {
396	            field_type_diffs(d, &format!("{prefix}[]"), r_inner, v_inner);
397	        }
398	        (FieldType::Object(r_map), FieldType::Object(v_map)) => {
399	            let keys: std::collections::BTreeSet<&String> =
400	                r_map.keys().chain(v_map.keys()).collect();
401	            for k in keys {
402	                match (r_map.get(k), v_map.get(k)) {
403	                    (Some(rf), Some(vf)) => field_diffs(d, &format!("{prefix}.{k}"), rf, vf),
404	                    (Some(_), None) => {
405	                        d.push(format!("{prefix}.{k}: DROPPED (in reference, not derived)"))
406	                    }
407	                    (None, Some(_)) => {
408	                        d.push(format!("{prefix}.{k}: ADDED (in derived, not reference)"))
409	                    }
410	                    (None, None) => {}
411	                }
412	            }
413	        }
414	        (FieldType::OneOf(r_branches), FieldType::OneOf(v_branches)) => {
415	            if r_branches.len() != v_branches.len() {
416	                d.push(format!(
417	                    "{prefix}: one_of branch count differs ({} vs {})",
418	                    r_branches.len(),
419	                    v_branches.len()
420	                ));
421	            }
422	            for (i, (rb, vb)) in r_branches.iter().zip(v_branches.iter()).enumerate() {
423	                field_type_diffs(d, &format!("{prefix}|{i}"), rb, vb);
424	            }
425	        }
426	        _ => {}
427	    }
428	}
429	
430	fn val_str(v: &Option<OwnedValue>) -> String {
431	    match v {
432	        Some(x) => format!("{x:?}"),
433	        None => "null".into(),
434	    }
435	}
436	
437	fn type_tag(t: &FieldType) -> String {
438	    match t {
439	        FieldType::String => "string".into(),
440	        FieldType::Integer => "integer".into(),
441	        FieldType::Float => "float".into(),
442	        FieldType::Boolean => "boolean".into(),
443	        FieldType::Any => "any".into(),
444	        FieldType::Enum(_) => "enum".into(),
445	        FieldType::OneOf(branches) => {
446	            let mut tags: Vec<String> = branches.iter().map(type_tag).collect();
447	            tags.sort();
448	            format!("one_of<{}>", tags.join("|"))
449	        }
450	        FieldType::Array(i) => format!("array<{}>", type_tag(i)),
451	        FieldType::Object(m) => {
452	            let mut entries: Vec<String> = m
453	                .iter()
454	                .map(|(k, v)| format!("{k}:{}", type_tag(&v.field_type)))
455	                .collect();
456	            entries.sort();
457	            format!("object{{{}}}", entries.join(","))
458	        }
459	    }
460	}
461	
462	fn constraint_tags(cs: &[Constraint]) -> Vec<String> {
463	    let mut v: Vec<String> = cs
464	        .iter()
465	        .map(|c| match c {
466	            Constraint::Min { value } => format!("min:{value}"),
467	            Constraint::Max { value } => format!("max:{value}"),
468	            Constraint::Pattern { regex } => format!("pattern:{regex}"),
469	            Constraint::OneOf { .. } => "oneof".into(),
470	            Constraint::RequiresField { field } => format!("requires:{field}"),
471	            Constraint::Custom { validator } => format!("custom:{validator}"),
472	        })
473	        .collect();
474	    v.sort();
475	    v
476	}
