//! Common schema field definitions for uniform `PluginSchema` structure across plugins.
//!
//! This module provides the canonical structs for repeated metadata, network, service,
//! and AI config blocks. Every plugin MUST embed or derive from these (via `#[serde(flatten)]`
//! or direct use) so that the schema contract is identical for introspection in SHM,
//! D-Bus, gRPC, MCP and GUI.
//!
//! ## Usage
//!
//! ```rust,ignore
//! #[derive(..., schemars::JsonSchema)]
//! pub struct MyState {
//!     /// Common metadata flattened for uniform top level.
//!     #[serde(flatten)]
//!     pub metadata: PluginMetadata,
//!
//!     #[serde(flatten)]
//!     pub network: Option<NetworkInterface>,
//!     // ...
//! }
//! ```
//!
//! Subids are NOT embedded in struct extensions; they are injected via
//! `inject_common_subids` *after* `schema_from_state` / `plugin_schema_from_json` +
//! `apply_state_defaults` (see plugin scaffold patterns in xray.rs, gb_software.rs).

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// Canonical per-plugin metadata block (uniformised contract).
///
/// Fields carry stable subids post-injection. Use `#[serde(flatten)]` to inline
/// at top level of `*State` so D-Bus `Get` / projection always sees `running`,
/// `version` etc. at the same paths.
///
/// Sensible defaults ensure a schema always materialises valid state.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct PluginMetadata {
    /// Whether a backing process / daemon for the plugin is live on the host.
    #[serde(default)]
    pub running: bool,

    /// Self-reported or supervisor-derived health (true = operational).
    #[serde(default = "default_true")]
    pub healthy: bool,

    /// Software / binary version string (semver or vcs).
    #[serde(default = "default_version")]
    pub version: String,

    /// Canonical software / package identifier (e.g. "xray-core", "gemma").
    #[serde(default)]
    pub software: String,

    /// Resolved runtime dependencies (package names, feature flags, etc).
    #[serde(default)]
    pub dependencies: Vec<String>,

    /// Optional authoritative OSCAL registry location (D-Bus path or file).
    #[serde(default)]
    pub oscal_source: Option<String>,

    /// Exposed MCP / tool surface for this plugin (arbitrary JSON per JSON Schema).
    /// Keep compatible shape across versions.
    #[serde(default = "default_tools")]
    pub tools: serde_json::Value,
}

fn default_true() -> bool {
    true
}

fn default_version() -> String {
    "1.0.0".to_owned()
}

fn default_tools() -> serde_json::Value {
    serde_json::json!([])
}

/// Common representation of a network interface in plugin schemas.
///
/// Embed with `#[serde(flatten)]` inside Network* state or use inside arrays.
/// Provides stable names for subid injection.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct NetworkInterface {
    /// IANA interface name (eth0, wlan0, br0, ...).
    #[serde(default)]
    pub name: String,

    /// MAC / link address.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mac: Option<String>,

    /// All configured addresses (CIDR strings).
    #[serde(default)]
    pub addresses: Vec<String>,

    /// Operational state (up, down, unknown).
    #[serde(default = "default_if_state")]
    pub state: String,

    /// MTU in bytes.
    #[serde(default = "default_mtu")]
    pub mtu: u32,

    /// Example of flatten for driver-specific tunables.
    #[serde(flatten)]
    pub driver_tunables: std::collections::HashMap<String, serde_json::Value>,
}

fn default_if_state() -> String {
    "unknown".to_owned()
}

fn default_mtu() -> u32 {
    1500
}

/// Canonical service configuration / status block.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct ServiceConfig {
    /// systemd / s6 unit name.
    #[serde(default)]
    pub name: String,

    /// Is the unit enabled at boot.
    #[serde(default)]
    pub enabled: bool,

    /// Whether current process is running.
    #[serde(default)]
    pub running: bool,

    /// Restart policy (always, on-failure, no).
    #[serde(default = "default_restart")]
    pub restart: String,

    /// Main PID if running.
    #[serde(default)]
    pub pid: Option<u32>,

    /// Human description of last state change reason.
    #[serde(default)]
    pub status: String,
}

fn default_restart() -> String {
    "on-failure".to_owned()
}

/// AI / LLM model configuration block for cognitive plugins.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct AIModelConfig {
    /// Base model identifier (ollama tag, huggingface, etc).
    #[serde(default = "default_ai_model")]
    pub model: String,

    /// Inference provider (ollama, openai, gemma, zeroclaw, ...).
    #[serde(default = "default_ai_provider")]
    pub provider: String,

    /// Sampling temperature.
    #[serde(default = "default_temp")]
    pub temperature: f32,

    /// Max tokens for generation.
    #[serde(default = "default_max_tokens")]
    pub max_tokens: u32,

    /// MCP tools registered for this model use (flattened/embedded form allowed).
    #[serde(default)]
    pub tools: Vec<String>,

    /// Provider-specific params (flattened for uniforms).
    #[serde(flatten)]
    pub provider_params: std::collections::HashMap<String, serde_json::Value>,
}

fn default_ai_model() -> String {
    "gemma:2b".to_owned()
}
fn default_ai_provider() -> String {
    "ollama".to_owned()
}
fn default_temp() -> f32 {
    0.7
}
fn default_max_tokens() -> u32 {
    2048
}

/// Inject OSCAL subid taxonomy entries for the common fields into an *already built*
/// `PluginSchema`.
///
/// Must be called after `schema_from_state(...)` (or `plugin_schema_from_json` +
/// `apply_state_defaults`) but before returning the schema from the plugin.
///
/// `plugin_name` seeds the subject in subids (lowercase, no spaces).
/// `sections` filters which groups get injected (e.g. `&["metadata", "network", "service", "ai"]`).
/// Empty or missing means "all known commons".
///
/// Subids follow AGENTS.md §4a exactly. `mut*` and `evt*` not auto-injected here.
pub fn inject_common_subids(
    schema: &mut op_state_store::PluginSchema,
    plugin_name: &str,
    sections: &[&str],
) {
    let inject_all = sections.is_empty();
    let has = |s: &str| inject_all || sections.iter().any(|x| *x == s);

    // Core metadata (obs for status-ish reads, exp for tools surface, src for oscal)
    if has("metadata") || has("common") {
        schema
            .subids
            .entry("running".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.running@v1", plugin_name));
        schema
            .subids
            .entry("healthy".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.healthy@v1", plugin_name));
        schema
            .subids
            .entry("version".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.version@v1", plugin_name));
        schema
            .subids
            .entry("software".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.software@v1", plugin_name));
        schema
            .subids
            .entry("dependencies".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.dependencies@v1", plugin_name));
        schema
            .subids
            .entry("oscal_source".to_string())
            .or_insert_with(|| format!("src.software.plugin.{}.oscal-source@v1", plugin_name));
        schema
            .subids
            .entry("tools".to_string())
            .or_insert_with(|| format!("exp.software.plugin.{}.tools@v1", plugin_name));
    }

    // Network block
    if has("network") || has("net") {
        schema
            .subids
            .entry("name".to_string())
            .or_insert_with(|| format!("obs.network.plugin.{}.interface.name@v1", plugin_name));
        schema
            .subids
            .entry("addresses".to_string())
            .or_insert_with(|| {
                format!("obs.network.plugin.{}.interface.addresses@v1", plugin_name)
            });
        schema
            .subids
            .entry("state".to_string())
            .or_insert_with(|| format!("obs.network.plugin.{}.interface.state@v1", plugin_name));
    }

    // Service block
    if has("service") || has("svc") {
        schema
            .subids
            .entry("enabled".to_string())
            .or_insert_with(|| {
                format!(
                    "obs.process-procedure.plugin.{}.service.enabled@v1",
                    plugin_name
                )
            });
        schema
            .subids
            .entry("running".to_string()) // may clash; last wins or use prefixed entry
            .or_insert_with(|| {
                format!(
                    "obs.process-procedure.plugin.{}.service.running@v1",
                    plugin_name
                )
            });
    }

    // AI / LLM block
    if has("ai") || has("model") || has("llm") {
        schema
            .subids
            .entry("model".to_string())
            .or_insert_with(|| format!("sch.software.plugin.{}.ai-model.model@v1", plugin_name));
        schema
            .subids
            .entry("provider".to_string())
            .or_insert_with(|| format!("sch.software.plugin.{}.ai-model.provider@v1", plugin_name));
    }
}

