//! Common schema blob sections — reusable typed fragments shared by 3+ plugins.
//!
//! Canonical home of the structs for repeated metadata, network, service, AI
//! config, and key-material blocks (moved from
//! `op-plugins/src/state_plugins/common/common_schema_fields.rs`, which now
//! re-exports this module). Every plugin embeds these instead of redefining
//! the fields, so each concept has ONE shape in every sealed blob and every
//! consumer — UI rendering, routing, compliance, enforcement, memory, audit
//! trail — reads it the same way.
//!
//! ## Usage
//!
//! ```rust,ignore
//! #[derive(..., schemars::JsonSchema)]
//! pub struct MyState {
//!     /// Common metadata flattened for uniform top level.
//!     #[serde(flatten)]
//!     pub metadata: PluginMetadata,
//!
//!     /// Or embedded as a named block with a plugin-scoped subid.
//!     #[schemars(extend("x-oscal-subid" = "obs.service.plugin.my-plugin.ai-model@v1"))]
//!     pub ai_model: AIModelConfig,
//! }
//! ```
//!
//! ## Subid policy (global uniqueness)
//!
//! Section fields deliberately carry **no** `x-oscal-subid` extensions: subid
//! values must be globally unique across plugins
//! (`all_plugin_subids_are_valid_and_unique`), so a fixed subid baked into a
//! shared struct would collide the moment two plugins embed it. Instead:
//!
//! - flattened sections get plugin-namespaced subids injected via
//!   [`inject_common_subids`] *after* `schema_from_state` /
//!   `plugin_schema_from_json` + `apply_state_defaults`;
//! - nested (non-flattened) sections are annotated on the *embedding field*,
//!   which is the only level `adapter::plugin_schema_from_json` ingests.
//!
//! ## Secrets policy
//!
//! No section ever carries secret material (blob identity rule: private keys
//! are never serialized). Key/credential fields hold *references* — a path,
//! an env-var name, a key id — never the secret itself.

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

/// Canonical per-plugin metadata block (uniformised contract).
///
/// Fields carry stable subids post-injection. Use `#[serde(flatten)]` to inline
/// at top level of `*State` so D-Bus `Get` / projection always sees `running`,
/// `version` etc. at the same paths.
///
/// Sensible defaults ensure a schema always materialises valid state.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct PluginMetadata {
    /// Whether a backing process / daemon for the plugin is live on the host.
    #[serde(default)]
    pub running: bool,

    /// Self-reported or supervisor-derived health (true = operational).
    #[serde(default = "default_true")]
    pub healthy: bool,

    /// Software / binary version string (semver or vcs).
    #[serde(default = "default_version")]
    pub version: String,

    /// Canonical software / package identifier (e.g. "xray-core", "gemma").
    #[serde(default)]
    pub software: String,

    /// Resolved runtime dependencies (package names, feature flags, etc).
    #[serde(default)]
    pub dependencies: Vec<String>,

    /// Optional authoritative OSCAL registry location (D-Bus path or file).
    #[serde(default)]
    pub oscal_source: Option<String>,

    /// Exposed MCP / tool surface for this plugin (arbitrary JSON per JSON Schema).
    /// Keep compatible shape across versions.
    #[serde(default = "default_tools")]
    pub tools: serde_json::Value,
}

fn default_true() -> bool {
    true
}

fn default_version() -> String {
    "1.0.0".to_owned()
}

fn default_tools() -> serde_json::Value {
    serde_json::json!([])
}

/// Common representation of a network interface in plugin schemas.
///
/// Embed with `#[serde(flatten)]` inside Network* state or use inside arrays.
/// Provides stable names for subid injection.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct NetworkInterface {
    /// IANA interface name (eth0, wlan0, br0, ...).
    #[serde(default)]
    pub name: String,

    /// MAC / link address.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mac: Option<String>,

    /// All configured addresses (CIDR strings).
    #[serde(default)]
    pub addresses: Vec<String>,

    /// Operational state (up, down, unknown).
    #[serde(default = "default_if_state")]
    pub state: String,

    /// MTU in bytes.
    #[serde(default = "default_mtu")]
    pub mtu: u32,

    /// Example of flatten for driver-specific tunables.
    #[serde(flatten)]
    pub driver_tunables: std::collections::HashMap<String, serde_json::Value>,
}

fn default_if_state() -> String {
    "unknown".to_owned()
}

fn default_mtu() -> u32 {
    1500
}

/// Canonical service configuration / status block.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct ServiceConfig {
    /// systemd / s6 unit name.
    #[serde(default)]
    pub name: String,

    /// Is the unit enabled at boot.
    #[serde(default)]
    pub enabled: bool,

    /// Whether current process is running.
    #[serde(default)]
    pub running: bool,

    /// Restart policy (always, on-failure, no).
    #[serde(default = "default_restart")]
    pub restart: String,

    /// Main PID if running.
    #[serde(default)]
    pub pid: Option<u32>,

    /// Human description of last state change reason.
    #[serde(default)]
    pub status: String,
}

fn default_restart() -> String {
    "on-failure".to_owned()
}

/// AI / LLM model configuration block for cognitive plugins.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default)]
pub struct AIModelConfig {
    /// Base model identifier (ollama tag, huggingface, etc).
    #[serde(default = "default_ai_model")]
    pub model: String,

    /// Inference provider (ollama, openai, gemma, zeroclaw, ...).
    #[serde(default = "default_ai_provider")]
    pub provider: String,

    /// Sampling temperature.
    #[serde(default = "default_temp")]
    pub temperature: f32,

    /// Max tokens for generation.
    #[serde(default = "default_max_tokens")]
    pub max_tokens: u32,

    /// MCP tools registered for this model use (flattened/embedded form allowed).
    #[serde(default)]
    pub tools: Vec<String>,

    /// Provider-specific params (flattened for uniforms).
    #[serde(flatten)]
    pub provider_params: std::collections::HashMap<String, serde_json::Value>,
}

fn default_ai_model() -> String {
    "gemma:2b".to_owned()
}
fn default_ai_provider() -> String {
    "ollama".to_owned()
}
fn default_temp() -> f32 {
    0.7
}
fn default_max_tokens() -> u32 {
    2048
}

/// Shared key-material reference block (wireguard, keypair, keyring, wgcf).
///
/// Public material only; the private key stays on disk behind
/// `private_key_path` and is never serialized into state or blobs.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, Default, PartialEq)]
pub struct SecurityKey {
    /// Key algorithm, e.g. "x25519", "ed25519", "rsa-4096".
    #[serde(default)]
    pub algorithm: String,

    /// Public key, base64/PEM as the algorithm dictates. Safe to serialize.
    #[serde(default)]
    pub public_key: String,

    /// Certificate (PEM) bound to the key, if any.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub certificate: Option<String>,

    /// Absolute path to the private key file. The key itself is never
    /// serialized.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub private_key_path: Option<String>,
}

/// Inject OSCAL subid taxonomy entries for the common fields into an *already built*
/// `PluginSchema`.
///
/// Must be called after `schema_from_state(...)` (or `plugin_schema_from_json` +
/// `apply_state_defaults`) but before returning the schema from the plugin.
///
/// `plugin_name` seeds the subject in subids (lowercase, no spaces).
/// `sections` filters which groups get injected (e.g. `&["metadata", "network", "service", "ai"]`).
/// Empty or missing means "all known commons".
///
/// Subids follow AGENTS.md §4a exactly. `mut*` and `evt*` not auto-injected here.
pub fn inject_common_subids(
    schema: &mut op_state_store::PluginSchema,
    plugin_name: &str,
    sections: &[&str],
) {
    let inject_all = sections.is_empty();
    let has = |s: &str| inject_all || sections.iter().any(|x| *x == s);

    // Core metadata (obs for status-ish reads, exp for tools surface, src for oscal)
    if has("metadata") || has("common") {
        schema
            .subids
            .entry("running".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.running@v1", plugin_name));
        schema
            .subids
            .entry("healthy".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.healthy@v1", plugin_name));
        schema
            .subids
            .entry("version".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.version@v1", plugin_name));
        schema
            .subids
            .entry("software".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.software@v1", plugin_name));
        schema
            .subids
            .entry("dependencies".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.dependencies@v1", plugin_name));
        schema
            .subids
            .entry("oscal_source".to_string())
            .or_insert_with(|| format!("src.software.plugin.{}.oscal-source@v1", plugin_name));
        schema
            .subids
            .entry("tools".to_string())
            .or_insert_with(|| format!("exp.software.plugin.{}.tools@v1", plugin_name));
    }

    // Network block
    if has("network") || has("net") {
        schema
            .subids
            .entry("name".to_string())
            .or_insert_with(|| format!("obs.network.plugin.{}.interface.name@v1", plugin_name));
        schema
            .subids
            .entry("addresses".to_string())
            .or_insert_with(|| {
                format!("obs.network.plugin.{}.interface.addresses@v1", plugin_name)
            });
        schema
            .subids
            .entry("state".to_string())
            .or_insert_with(|| format!("obs.network.plugin.{}.interface.state@v1", plugin_name));
    }

    // Service block
    if has("service") || has("svc") {
        schema
            .subids
            .entry("enabled".to_string())
            .or_insert_with(|| {
                format!(
                    "obs.process-procedure.plugin.{}.service.enabled@v1",
                    plugin_name
                )
            });
        schema
            .subids
            .entry("running".to_string()) // may clash; last wins or use prefixed entry
            .or_insert_with(|| {
                format!(
                    "obs.process-procedure.plugin.{}.service.running@v1",
                    plugin_name
                )
            });
    }

    // AI / LLM block
    if has("ai") || has("model") || has("llm") {
        schema
            .subids
            .entry("model".to_string())
            .or_insert_with(|| format!("sch.software.plugin.{}.ai-model.model@v1", plugin_name));
        schema
            .subids
            .entry("provider".to_string())
            .or_insert_with(|| format!("sch.software.plugin.{}.ai-model.provider@v1", plugin_name));
    }

    // Key material block (public references only; never secret material)
    if has("key") || has("security") {
        schema
            .subids
            .entry("algorithm".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.key.algorithm@v1", plugin_name));
        schema
            .subids
            .entry("public_key".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.key.public-key@v1", plugin_name));
        schema
            .subids
            .entry("private_key_path".to_string())
            .or_insert_with(|| {
                format!("obs.software.plugin.{}.key.private-key-path@v1", plugin_name)
            });
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::adapter::plugin_schema_from_json;
    use op_state_store::FieldType;

    #[derive(Debug, Serialize, Deserialize, JsonSchema)]
    #[schemars(extend("x-oscal-subid" = "sch.software.plugin.section-host.schema@v1"))]
    struct SectionHostState {
        #[schemars(extend("x-oscal-subid" = "obs.software.plugin.section-host.metadata@v1"))]
        metadata: PluginMetadata,
        #[schemars(extend("x-oscal-subid" = "obs.network.plugin.section-host.interface@v1"))]
        interface: NetworkInterface,
        #[schemars(extend("x-oscal-subid" = "obs.service.plugin.section-host.service@v1"))]
        service: ServiceConfig,
        #[schemars(extend("x-oscal-subid" = "obs.service.plugin.section-host.model@v1"))]
        model: AIModelConfig,
        #[schemars(extend("x-oscal-subid" = "obs.software.plugin.section-host.key@v1"))]
        key: SecurityKey,
    }

    fn host_schema() -> op_state_store::PluginSchema {
        let root = serde_json::to_value(schemars::schema_for!(SectionHostState)).unwrap();
        plugin_schema_from_json("section_host", "1.0.0", "test host", &root)
    }

    #[test]
    fn embedded_sections_expand_to_typed_objects() {
        let schema = host_schema();
        for field in ["metadata", "interface", "service", "model", "key"] {
            let f = schema
                .fields
                .get(field)
                .unwrap_or_else(|| panic!("{field} missing"));
            match &f.field_type {
                FieldType::Object(props) => assert!(!props.is_empty(), "{field} expanded empty"),
                other => panic!("{field}: expected object, got {other:?}"),
            }
        }
        let meta = match &schema.fields["metadata"].field_type {
            FieldType::Object(props) => props,
            _ => unreachable!(),
        };
        assert!(matches!(meta["running"].field_type, FieldType::Boolean));
        assert!(matches!(
            meta["dependencies"].field_type,
            FieldType::Array(_)
        ));
    }

    #[test]
    fn embedding_field_subids_are_ingested_and_section_fields_add_none() {
        let schema = host_schema();
        assert_eq!(
            schema.subids.get("metadata"),
            Some(&"obs.software.plugin.section-host.metadata@v1".to_string())
        );
        // Exactly the root subid + the five embedding-field subids: the
        // sections themselves contribute nothing to the uniqueness map.
        assert_eq!(schema.subids.len(), 6);
    }

    #[test]
    fn injected_subids_are_plugin_namespaced_and_never_collide() {
        let mut a = op_state_store::PluginSchema::builder("alpha").build();
        let mut b = op_state_store::PluginSchema::builder("beta").build();
        inject_common_subids(&mut a, "alpha", &[]);
        inject_common_subids(&mut b, "beta", &[]);
        assert!(!a.subids.is_empty());
        assert_eq!(a.subids.len(), b.subids.len());
        for (key, subid) in &a.subids {
            assert!(subid.contains(".alpha."), "{key}: {subid}");
            assert_ne!(Some(subid), b.subids.get(key), "collision on {key}");
        }
    }

    #[test]
    fn sections_never_serialize_secret_material() {
        let schema_json = serde_json::to_string(&schemars::schema_for!(SecurityKey)).unwrap();
        assert!(!schema_json.contains("\"private_key\""));
        let key = SecurityKey {
            algorithm: "x25519".into(),
            public_key: "pub".into(),
            certificate: None,
            private_key_path: Some("/etc/keys/wg0.key".into()),
        };
        let out = serde_json::to_string(&key).unwrap();
        assert!(out.contains("private_key_path"));
        assert!(!out.contains("BEGIN PRIVATE KEY"));
    }

    #[test]
    fn section_schemas_are_deterministic() {
        let a = serde_json::to_string(&schemars::schema_for!(PluginMetadata)).unwrap();
        let b = serde_json::to_string(&schemars::schema_for!(PluginMetadata)).unwrap();
        assert_eq!(a, b);
    }
}

