/// `sections` filters which groups get injected (e.g. `&["metadata", "network", "service", "ai"]`).
/// Empty or missing means "all known commons".
///
/// Subids follow AGENTS.md §4a exactly. `mut*` and `evt*` not auto-injected here.
pub fn inject_common_subids(
    schema: &mut op_state_store::PluginSchema,
    plugin_name: &str,
    sections: &[&str],
) {
    let inject_all = sections.is_empty();
    let has = |s: &str| inject_all || sections.iter().any(|x| *x == s);

    // Core metadata (obs for status-ish reads, exp for tools surface, src for oscal)
    if has("metadata") || has("common") {
        schema
            .subids
            .entry("running".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.running@v1", plugin_name));
        schema
            .subids
            .entry("healthy".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.healthy@v1", plugin_name));
        schema
            .subids
            .entry("version".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.version@v1", plugin_name));
        schema
            .subids
            .entry("software".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.software@v1", plugin_name));
        schema
            .subids
            .entry("dependencies".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.dependencies@v1", plugin_name));
        schema
            .subids
            .entry("oscal_source".to_string())
            .or_insert_with(|| format!("src.software.plugin.{}.oscal-source@v1", plugin_name));
        schema
            .subids
            .entry("tools".to_string())
            .or_insert_with(|| format!("exp.software.plugin.{}.tools@v1", plugin_name));
    }

    // Network block
    if has("network") || has("net") {
        schema
            .subids
            .entry("name".to_string())
            .or_insert_with(|| format!("obs.network.plugin.{}.interface.name@v1", plugin_name));
        schema
            .subids
            .entry("addresses".to_string())
            .or_insert_with(|| {
                format!("obs.network.plugin.{}.interface.addresses@v1", plugin_name)
            });
        schema
            .subids
            .entry("state".to_string())
            .or_insert_with(|| format!("obs.network.plugin.{}.interface.state@v1", plugin_name));
    }

    // Service block
    if has("service") || has("svc") {
        schema
            .subids
            .entry("enabled".to_string())
            .or_insert_with(|| {
                format!(
                    "obs.process-procedure.plugin.{}.service.enabled@v1",
                    plugin_name
                )
            });
        schema
            .subids
            .entry("running".to_string()) // may clash; last wins or use prefixed entry
            .or_insert_with(|| {
                format!(
                    "obs.process-procedure.plugin.{}.service.running@v1",
                    plugin_name
                )
            });
    }

    // AI / LLM block
    if has("ai") || has("model") || has("llm") {
        schema
            .subids
            .entry("model".to_string())
            .or_insert_with(|| format!("sch.software.plugin.{}.ai-model.model@v1", plugin_name));
        schema
            .subids
            .entry("provider".to_string())
            .or_insert_with(|| format!("sch.software.plugin.{}.ai-model.provider@v1", plugin_name));
    }

    // Key material block (public references only; never secret material)
    if has("key") || has("security") {
        schema
            .subids
            .entry("algorithm".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.key.algorithm@v1", plugin_name));
        schema
            .subids
            .entry("public_key".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.key.public-key@v1", plugin_name));
        schema
            .subids
            .entry("private_key_path".to_string())
            .or_insert_with(|| {
                format!("obs.software.plugin.{}.key.private-key-path@v1", plugin_name)
            });
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::adapter::plugin_schema_from_json;
    use op_state_store::FieldType;

    #[derive(Debug, Serialize, Deserialize, JsonSchema)]
    #[schemars(extend("x-oscal-subid" = "sch.software.plugin.section-host.schema@v1"))]
    struct SectionHostState {
        #[schemars(extend("x-oscal-subid" = "obs.software.plugin.section-host.metadata@v1"))]
        metadata: PluginMetadata,
        #[schemars(extend("x-oscal-subid" = "obs.network.plugin.section-host.interface@v1"))]
        interface: NetworkInterface,
        #[schemars(extend("x-oscal-subid" = "obs.service.plugin.section-host.service@v1"))]
        service: ServiceConfig,
        #[schemars(extend("x-oscal-subid" = "obs.service.plugin.section-host.model@v1"))]
        model: AIModelConfig,
        #[schemars(extend("x-oscal-subid" = "obs.software.plugin.section-host.key@v1"))]
        key: SecurityKey,
    }

    fn host_schema() -> op_state_store::PluginSchema {
        let root = serde_json::to_value(schemars::schema_for!(SectionHostState)).unwrap();
        plugin_schema_from_json("section_host", "1.0.0", "test host", &root)
    }

    #[test]
    fn embedded_sections_expand_to_typed_objects() {
        let schema = host_schema();
        for field in ["metadata", "interface", "service", "model", "key"] {
            let f = schema
                .fields
                .get(field)
                .unwrap_or_else(|| panic!("{field} missing"));
            match &f.field_type {
                FieldType::Object(props) => assert!(!props.is_empty(), "{field} expanded empty"),
                other => panic!("{field}: expected object, got {other:?}"),
            }
        }
        let meta = match &schema.fields["metadata"].field_type {
            FieldType::Object(props) => props,
            _ => unreachable!(),
        };
        assert!(matches!(meta["running"].field_type, FieldType::Boolean));
        assert!(matches!(
            meta["dependencies"].field_type,
            FieldType::Array(_)
        ));
    }

    #[test]
    fn embedding_field_subids_are_ingested_and_section_fields_add_none() {
        let schema = host_schema();
        assert_eq!(
            schema.subids.get("metadata"),
            Some(&"obs.software.plugin.section-host.metadata@v1".to_string())
        );
        // Exactly the root subid + the five embedding-field subids: the
        // sections themselves contribute nothing to the uniqueness map.
        assert_eq!(schema.subids.len(), 6);
    }

    #[test]
    fn injected_subids_are_plugin_namespaced_and_never_collide() {
        let mut a = op_state_store::PluginSchema::builder("alpha").build();
        let mut b = op_state_store::PluginSchema::builder("beta").build();
        inject_common_subids(&mut a, "alpha", &[]);
        inject_common_subids(&mut b, "beta", &[]);
        assert!(!a.subids.is_empty());
        assert_eq!(a.subids.len(), b.subids.len());
        for (key, subid) in &a.subids {
            assert!(subid.contains(".alpha."), "{key}: {subid}");
            assert_ne!(Some(subid), b.subids.get(key), "collision on {key}");
        }
    }

    #[test]
    fn sections_never_serialize_secret_material() {
        let schema_json = serde_json::to_string(&schemars::schema_for!(SecurityKey)).unwrap();
        assert!(!schema_json.contains("\"private_key\""));
        let key = SecurityKey {
            algorithm: "x25519".into(),
            public_key: "pub".into(),
            certificate: None,
            private_key_path: Some("/etc/keys/wg0.key".into()),
        };
        let out = serde_json::to_string(&key).unwrap();
        assert!(out.contains("private_key_path"));
        assert!(!out.contains("BEGIN PRIVATE KEY"));
    }

    #[test]
    fn section_schemas_are_deterministic() {
        let a = serde_json::to_string(&schemars::schema_for!(PluginMetadata)).unwrap();
        let b = serde_json::to_string(&schemars::schema_for!(PluginMetadata)).unwrap();
        assert_eq!(a, b);
    }
}

