//! Common schema blob sections — reusable typed fragments shared by 3+ plugins.
//!
//! These structs are the single source of truth for schema shape that repeats
//! across plugins (status/health metadata, network interfaces, service config,
//! AI model config, key material references). A plugin embeds a section in its
//! state struct instead of redefining the fields, so every consumer of the
//! sealed blob — UI rendering, routing, compliance, enforcement, memory, audit
//! trail — sees one uniform shape for the same concept.
//!
//! ## Subid policy (global uniqueness)
//!
//! Section fields deliberately carry **no** `x-oscal-subid` annotations: subid
//! values must be globally unique across all plugins
//! (`all_plugin_subids_are_valid_and_unique`), so a fixed subid baked into a
//! shared struct would collide the moment two plugins embed it. Instead the
//! embedding plugin annotates the *field that holds the section* with its own
//! plugin-scoped subid:
//!
//! ```ignore
//! #[derive(schemars::JsonSchema, Serialize, Deserialize)]
//! pub struct MyPluginState {
//!     #[schemars(extend("x-oscal-subid" = "obs.software.plugin.my-plugin.metadata@v1"))]
//!     pub metadata: PluginMetadata,
//! }
//! ```
//!
//! `adapter::plugin_schema_from_json` ingests subids only from top-level
//! properties, so nested section fields never enter the uniqueness map.
//!
//! ## Secrets policy
//!
//! No section ever carries secret material (blob identity rule: private keys
//! are never serialized). Key/credential fields hold *references* — a path,
//! an env-var name, a key id — never the secret itself.

use serde::{Deserialize, Serialize};

/// Shared plugin liveness/provenance metadata (xray-shaped: status, running,
/// healthy, version, software, dependencies, oscal_source, tools).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, schemars::JsonSchema)]
pub struct PluginMetadata {
    /// Lifecycle status, e.g. "ready", "active", "degraded", "stopped".
    #[serde(default)]
    pub status: String,
    /// Whether the managed process/service is currently running.
    #[serde(default)]
    pub running: bool,
    /// Whether the last health probe succeeded.
    #[serde(default)]
    pub healthy: bool,
    /// Version of the managed software (not the plugin contract version).
    #[serde(default)]
    pub version: String,
    /// Name of the managed software package or daemon.
    #[serde(default)]
    pub software: String,
    /// Runtime dependencies (package or service names).
    #[serde(default)]
    pub dependencies: Vec<String>,
    /// OSCAL component-definition source locator for compliance mapping.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub oscal_source: Option<String>,
    /// Tool/command surface names exposed by the managed software.
    #[serde(default)]
    pub tools: Vec<String>,
}

/// Shared network interface shape (net, wireguard, ovsdb_bridge, openflow).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, schemars::JsonSchema)]
pub struct NetworkInterface {
    /// Interface name, e.g. "wg0", "br-ovs", "eth0".
    #[serde(default)]
    pub interface: String,
    /// Address in CIDR form, e.g. "10.0.0.2/24".
    #[serde(default)]
    pub address: String,
    /// MTU in bytes; None = kernel default.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mtu: Option<u32>,
    /// Bridge this interface is enslaved to, if any.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bridge_name: Option<String>,
    /// Listen/service port bound on this interface, if any.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub port: Option<u16>,
}

/// Shared supervised-service configuration (xray, s6, systemd, cron, fail2ban).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ServiceConfig {
    /// Whether the service is enabled (started under supervision at boot).
    #[serde(default)]
    pub enabled: bool,
    /// TCP/UDP port the service listens on, if any.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub socket_port: Option<u16>,
    /// Absolute path to the service's config file.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub config_path: Option<String>,
    /// Absolute path to the service's pid file, if it writes one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pid_file: Option<String>,
}

/// Shared AI model configuration (cognitive_mcp, compact_mcp, antigravity_chat,
/// gemma_brain, embedding_model, large_language_model).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, schemars::JsonSchema)]
pub struct AiModelConfig {
    /// Provider-scoped model identifier, e.g. "gemma3:4b", "claude-sonnet-5".
    #[serde(default)]
    pub model_id: String,
    /// Human-readable model name for UI display.
    #[serde(default)]
    pub model_name: String,
    /// Auth mechanism, e.g. "none", "api-key", "oauth", "chrome_profile".
    #[serde(default)]
    pub auth_method: String,
    /// Reference to the credential (env-var name or keyring locator) — never
    /// the secret itself.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub api_key_ref: Option<String>,
    /// Whether the model answered its last availability probe.
    #[serde(default)]
    pub available: bool,
}

/// Shared key-material reference (wireguard, keypair, keyring, wgcf).
/// Public material only; private keys stay on disk behind `private_key_path`.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, schemars::JsonSchema)]
pub struct SecurityKey {
    /// Key algorithm, e.g. "x25519", "ed25519", "rsa-4096".
    #[serde(default)]
    pub algorithm: String,
    /// Public key, base64/PEM as the algorithm dictates. Safe to serialize.
    #[serde(default)]
    pub public_key: String,
    /// Certificate (PEM) bound to the key, if any.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub certificate: Option<String>,
    /// Absolute path to the private key file. The key itself is never
    /// serialized into state or blobs.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub private_key_path: Option<String>,
}

