//! # op-blob — schema-coupled plugin object blobs
//!
//! Canonical implementation of the blob architecture
//! (docs: schema-coupled-plugin-blob-reflection whitepaper,
//! BLOB_ARCHITECTURE_SYNTHESIS). Drop-in replacement for the first-pass
//! `op-grpc-bridge::plugin_object_blob` module — that module now re-exports
//! this crate.
//!
//! ```text
//! PluginSchema (op-state-store, SINGLE SOURCE OF TRUTH)
//!   -> blobify_plugin_schema[_with_identity]
//!   -> PluginObjectBlob      schema_json + schema_hash
//!                            D-Bus identity + gRPC identity + descriptor set
//!                            method manifest (subid, capability, side effect)
//!                            WG-keypair account identity (public half only)
//!   -> seal() / BlobRef      zero-copy sectioned byte image, hash-verified
//!   -> BlobStore             /dev/shm/opdbus/plugin-blobs/<id>.<hash16>.blob
//!   -> btrfs image           mountable deployment unit (filesystem in blob)
//! ```
//!
//! Non-negotiable rules carried over:
//! 1. `PluginSchema` is the source of truth; the blob is a frozen projection.
//! 2. One D-Bus object, one blob, one schema hash.
//! 3. Reflection advertises only active blobs (the bridge's
//!    `ActiveReflectionCatalog` consumes `PluginObjectBlob` unchanged).
//! 4. The WireGuard keypair is the identity; its session persists for the
//!    life of the account.

pub mod adapter;
pub mod blob;
pub mod btrfs;
pub mod descriptor;
pub mod identity;
pub mod sealed;
pub mod sections;
pub mod store;

pub use adapter::{
    apply_state_defaults, method_decl_from_schemars_with_output, plugin_schema_from_json,
    schema_diffs, AckOutput, EmptyInput,
};
pub use blob::{
    blobify_plugin_schema, blobify_plugin_schema_with_identity, canonical_plugin_id,
    canonical_schema_bytes, canonical_simd_bytes, sanitize_blob_component, sanitize_proto_ident,
    sha256_hex, to_pascal_ident, BlobMethod, DbusObjectIdentity, GrpcObjectIdentity,
    PluginObjectBlob, OBJECT_BLOB_SHM_DIR,
};
pub use identity::{BlobIdentity, SessionBinding, SessionLifespan, WgKeypair};
pub use sections::{
    AiModelConfig, NetworkInterface, PluginMetadata, SecurityKey, ServiceConfig,
};
pub use sealed::BlobRef;
pub use store::BlobStore;

