    2048
}

/// Inject OSCAL subid taxonomy entries for the common fields into an *already built*
/// `PluginSchema`.
///
/// Must be called after `schema_from_state(...)` (or `plugin_schema_from_json` +
/// `apply_state_defaults`) but before returning the schema from the plugin.
///
/// `plugin_name` seeds the subject in subids (lowercase, no spaces).
/// `sections` filters which groups get injected (e.g. `&["metadata", "network", "service", "ai"]`).
/// Empty or missing means "all known commons".
///
/// Subids follow AGENTS.md §4a exactly. `mut*` and `evt*` not auto-injected here.
pub fn inject_common_subids(
    schema: &mut op_state_store::PluginSchema,
    plugin_name: &str,
    sections: &[&str],
) {
    let inject_all = sections.is_empty();
    let has = |s: &str| inject_all || sections.iter().any(|x| *x == s);

    // Core metadata (obs for status-ish reads, exp for tools surface, src for oscal)
    if has("metadata") || has("common") {
        schema
            .subids
            .entry("running".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.running@v1", plugin_name));
        schema
            .subids
            .entry("healthy".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.healthy@v1", plugin_name));
        schema
            .subids
            .entry("version".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.version@v1", plugin_name));
        schema
            .subids
            .entry("software".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.software@v1", plugin_name));
        schema
            .subids
            .entry("dependencies".to_string())
            .or_insert_with(|| format!("obs.software.plugin.{}.dependencies@v1", plugin_name));
        schema
            .subids
            .entry("oscal_source".to_string())
            .or_insert_with(|| format!("src.software.plugin.{}.oscal-source@v1", plugin_name));
        schema
            .subids
            .entry("tools".to_string())
            .or_insert_with(|| format!("exp.software.plugin.{}.tools@v1", plugin_name));
    }

    // Network block
    if has("network") || has("net") {
        schema
            .subids
            .entry("name".to_string())
            .or_insert_with(|| format!("obs.network.plugin.{}.interface.name@v1", plugin_name));
        schema
            .subids
            .entry("addresses".to_string())
            .or_insert_with(|| {
                format!("obs.network.plugin.{}.interface.addresses@v1", plugin_name)
            });
        schema
            .subids
            .entry("state".to_string())
            .or_insert_with(|| format!("obs.network.plugin.{}.interface.state@v1", plugin_name));
    }

    // Service block
    if has("service") || has("svc") {
        schema
            .subids
            .entry("enabled".to_string())
            .or_insert_with(|| {
                format!(
                    "obs.process-procedure.plugin.{}.service.enabled@v1",
                    plugin_name
                )
            });
        schema
            .subids
            .entry("running".to_string()) // may clash; last wins or use prefixed entry
            .or_insert_with(|| {
                format!(
                    "obs.process-procedure.plugin.{}.service.running@v1",
                    plugin_name
                )
            });
    }

    // AI / LLM block
    if has("ai") || has("model") || has("llm") {
        schema
            .subids
            .entry("model".to_string())
            .or_insert_with(|| format!("sch.software.plugin.{}.ai-model.model@v1", plugin_name));
        schema
            .subids
            .entry("provider".to_string())
            .or_insert_with(|| format!("sch.software.plugin.{}.ai-model.provider@v1", plugin_name));
    }
}

