#[cfg(test)]
mod tests {
    use super::*;
    use crate::state_plugins::common::oscal::validate_subid;
    use crate::state_plugins::schemars_adapter::schema_diffs;
    use serde_json::Value as JVal;

    fn collect_subids(value: &JVal, out: &mut Vec<String>) {
        if let Some(obj) = value.as_object() {
            if let Some(JVal::String(subid)) = obj.get("x-oscal-subid") {
                out.push(subid.clone());
            }
            for v in obj.values() {
                collect_subids(v, out);
            }
        }
        if let Some(arr) = value.as_array() {
            for v in arr {
                collect_subids(v, out);
            }
        }
    }

    #[test]
    fn derived_schema_matches_hand_rolled() {
        let golden = super::adc_schema_golden();
        let derived = super::adc_schema();
        let diffs = schema_diffs(&golden, &derived);
        // Tolerate serialization diffs (serde_json vs simd, numeric repr, key order on objects).
        // Critical contract: subids + schema identity + field presence must not drift.
        assert!(
            !diffs.iter().any(|d| d.contains("subid") || d.contains("sch.") || d.contains("mut.") || d.contains("obs.") || d.contains("src.") || d.contains("exp.") || d.contains("actor_id") || d.contains("capability_id")),
            "critical drift on subids or accountability fields: {:#?}", diffs
        );
    }

    #[test]
    fn all_subids_are_valid() {
        let raw = serde_json::to_value(schemars::schema_for!(AdcState)).unwrap();
        let mut subids = Vec::new();
        collect_subids(&raw, &mut subids);
        assert!(!subids.is_empty());
        for subid in subids {
            assert!(
                validate_subid(&subid).is_ok(),
                "invalid subid: {subid}"
            );
        }
        // Also validate the method subids (hardcoded in schema builder) are covered by pattern
        assert!(validate_subid("obs.software.plugin.adc.status.get@v1").is_ok());
        assert!(validate_subid("mut.software.plugin.adc.configured.set@v1").is_ok());
    }
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new(PLUGIN_NAME, |_ctx| std::sync::Arc::new(AdcPlugin::new()))
}

